<!doctype html><html lang="es"><head><meta charset="utf-8"><title>{{ $quotation->quotation_number }}</title><style>body{font-family:DejaVu Sans,sans-serif;color:#243247;font-size:12px;margin:38px}header{border-bottom:3px solid #615fff;padding-bottom:16px}h1{font-size:25px;margin:10px 0}h2{font-size:15px;margin:30px 0 10px}.muted{color:#64748b}.row{width:100%;margin-top:22px}.row td{width:50%;vertical-align:top}table.items{width:100%;border-collapse:collapse;margin-top:20px}table.items th{background:#eef0ff;text-align:left}table.items th,table.items td{padding:10px;border-bottom:1px solid #d9deeb}.right{text-align:right}.totals{margin:22px 0 0 auto;width:45%}.totals td{padding:5px}.total{font-size:17px;font-weight:bold;color:#4137ae}.note{margin-top:24px;padding:12px;background:#f6f7fb}</style></head><body><header><strong>{{ $quotation->tenant->name }}</strong><span class="muted" style="float:right">PROPUESTA COMERCIAL</span><h1>Presupuesto {{ $quotation->quotation_number }}</h1><span class="muted">Emitido el {{ $quotation->created_at->copy()->timezone($quotation->tenant->timezone)->format('d/m/Y') }} · Válido hasta {{ $quotation->valid_until?->format('d/m/Y') ?? 'A confirmar' }}</span></header><table class="row"><tr><td><strong>Cliente</strong><p>{{ $quotation->customer_snapshot['first_name'] }} {{ $quotation->customer_snapshot['last_name'] }}<br>{{ $quotation->customer_snapshot['document_type'] ?? '' }} {{ $quotation->customer_snapshot['document_number'] ?? '' }}</p>@if($quotation->address_snapshot)<p>{{ $quotation->address_snapshot['street'] }} {{ $quotation->address_snapshot['street_number'] }} · {{ $quotation->address_snapshot['city'] }}, {{ $quotation->address_snapshot['province'] }}</p>@endif</td><td><strong>Asesor comercial</strong><p>{{ $quotation->seller?->name }}</p></td></tr></table><h2>Productos</h2><table class="items"><thead><tr><th>Descripción</th><th class="right">Cantidad</th><th class="right">Precio</th><th class="right">Total</th></tr></thead><tbo